use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn main() {
    tauri_build::build();
    embed_pet_assets();
}

/// Embed the shipped final-art frames so the native pet window has zero
/// runtime file dependencies. The generated file is compiled into the Tauri
/// binary; this keeps the portable/NSIS output a single executable.
fn embed_pet_assets() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let root = manifest_dir.join("../../../public/assets/pet/anim");
    let root = root.canonicalize().unwrap_or(root);
    println!("cargo:rerun-if-changed={}", root.display());

    let mut files = Vec::new();
    collect_pngs(&root, &mut files);
    files.sort();
    if files.is_empty() {
        panic!("native pet assets missing: {}", root.display());
    }

    let out_dir = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    let target = out_dir.join("pet_assets.rs");
    let mut source = String::from("// @generated by build.rs — do not edit\n");
    source.push_str("pub static PET_PNGS: &[(&str, &[u8])] = &[\n");
    for path in &files {
        let rel = path
            .strip_prefix(&root)
            .unwrap_or(path)
            .to_string_lossy()
            .replace('\\', "/");
        let abs = path.canonicalize().unwrap_or_else(|_| path.clone());
        source.push_str(&format!(
            "    ({:?}, include_bytes!({:?})),\n",
            rel,
            abs.to_string_lossy()
        ));
    }
    source.push_str("];\n");
    fs::write(&target, source).expect("write pet_assets.rs");
    println!("cargo:rerun-if-changed={}", target.display());
}

fn collect_pngs(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(dir) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_pngs(&path, out);
        } else if path.extension().and_then(|e| e.to_str()) == Some("png") {
            out.push(path);
        }
    }
}
